function maxSubstringLength(s) {
  const n = s.length;
  const first = new Map();
  const last = new Map();
  for (let i = 0; i < n; i++) {
    if (!first.has(s[i])) {
      first.set(s[i], i);
    }
    last.set(s[i], i);
  }

  let best = -1;
  for (const start of first.values()) {
    let end = start;
    for (let i = start; i < n; i++) {
      if (first.get(s[i]) < start) {
        break;
      }
      end = Math.max(end, last.get(s[i]));
      if (i === end && end - start + 1 < n) {
        best = Math.max(best, end - start + 1);
      }
    }
  }
  return best;
}

