function maxSubstringLength(s) {
  const total = {};
  for (const ch of s) total[ch] = (total[ch] || 0) + 1;
  let answer = -1;
  for (let i = 0; i < s.length; i++) {
    const inside = {};
    for (let j = i; j < s.length; j++) {
      inside[s[j]] = (inside[s[j]] || 0) + 1;
      if (j - i + 1 === s.length) continue;
      const closed = Object.keys(inside).every(ch => inside[ch] === total[ch]);
      if (closed && j - i + 1 > answer) answer = j - i + 1;
    }
  }
  return answer;
}

