function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const letters = 'abcdefghijklmnopqrstuvwxyz'.split('');
  for (let i = letters.length - 1; i > 0; i--) {
    const j = int(0, i);
    [letters[i], letters[j]] = [letters[j], letters[i]];
  }
  if (size === 'small') {
    if (rand() < 0.5) {
      const alpha = letters.slice(0, int(1, 4));
      return [Array.from({ length: int(2, 10) }, () => alpha[int(0, alpha.length - 1)]).join('')];
    }
  }
  // Build blocks that each use their own letters, then sometimes nest one block inside another.
  const target = size === 'large' ? 10000 : int(2, 12);
  const groups = Math.min(int(1, 6), target);
  const alphabets = [];
  let used = 0;
  for (let g = 0; g < groups; g++) {
    const count = int(1, 4);
    alphabets.push(letters.slice(used, used + count));
    used += count;
  }
  const lengths = alphabets.map(() => 1);
  for (let extra = target - groups; extra > 0; extra--) lengths[int(0, groups - 1)]++;
  const blocks = alphabets.map((alpha, g) => Array.from({ length: lengths[g] }, () => alpha[int(0, alpha.length - 1)]).join(''));
  if (blocks.length >= 2 && rand() < 0.4) {
    const outer = blocks.shift();
    const cut = int(0, outer.length);
    blocks[0] = outer.slice(0, cut) + blocks[0] + outer.slice(cut);
  }
  let s = blocks.join('');
  if (s.length < 2) s += s;
  return [s];
}
